import { useRef, useState, type KeyboardEvent } from "react";
import "./TimeList.css";

export type TimeState = "past" | "next" | "later";

export interface TimeItem {
  readonly name: string;
  readonly time: string;
  readonly state: TimeState;
}

export interface TimeListProps {
  readonly items: readonly TimeItem[];
  readonly label?: string;
}

export function TimeList({ items, label = "Daily times" }: TimeListProps) {
  const rowRefs = useRef<(HTMLLIElement | null)[]>([]);

  const initialIndex = Math.max(
    0,
    items.findIndex((item) => item.state === "next"),
  );
  const [activeIndex, setActiveIndex] = useState<number>(initialIndex);

  if (items.length === 0) {
    return (
      <section className="myelin-timelist" aria-label={label}>
        <p className="myelin-timelist__empty">No times today.</p>
      </section>
    );
  }

  // Keep the roving tab stop valid if the items shrink.
  const tabStop = Math.min(activeIndex, items.length - 1);
  const last = items.length - 1;

  function focusRow(index: number) {
    rowRefs.current[index]?.focus();
  }

  function handleKeyDown(event: KeyboardEvent<HTMLLIElement>, index: number) {
    switch (event.key) {
      case "ArrowDown":
      case "ArrowRight":
        event.preventDefault();
        focusRow(Math.min(index + 1, last));
        break;
      case "ArrowUp":
      case "ArrowLeft":
        event.preventDefault();
        focusRow(Math.max(index - 1, 0));
        break;
      case "Home":
        event.preventDefault();
        focusRow(0);
        break;
      case "End":
        event.preventDefault();
        focusRow(last);
        break;
      default:
        break;
    }
  }

  return (
    <section className="myelin-timelist" aria-label={label}>
      <ol className="myelin-timelist__list">
        {items.map((item, index) => (
          <li
            key={`${item.name}-${item.time}`}
            ref={(el) => {
              rowRefs.current[index] = el;
            }}
            className="myelin-timelist__item"
            data-state={item.state}
            aria-current={item.state === "next" ? "time" : undefined}
            tabIndex={index === tabStop ? 0 : -1}
            onFocus={() => setActiveIndex(index)}
            onKeyDown={(event) => handleKeyDown(event, index)}
          >
            <span className="myelin-timelist__name">{item.name}</span>
            <time className="myelin-timelist__time">{item.time}</time>
          </li>
        ))}
      </ol>
    </section>
  );
}
