.myelin-timelist__item[data-state="next"] {
  background-color: var(--myelin-accent-soft);
  font-weight: 600;
}

.myelin-timelist__item[data-state="next"] .myelin-timelist__time {
  color: var(--myelin-accent);
}

/* Later: plain, at full strength but not highlighted. */
.myelin-timelist__item[data-state="later"] {
  opacity: 0.85;
}

.myelin-timelist__empty {
  margin: 0;
  color: var(--myelin-muted);
}

@media (prefers-reduced-motion: reduce) {
  .myelin-timelist__item {
    transition: none;
  }
